% Decision variables for each digit of the PIN
var 1..9: a; % First digit cannot be 0
var 0..9: b;
var 0..9: c;
var 0..9: d;

% Constraints
constraint all_different([a, b, c, d]); % No two digits are the same

% cd is 3 times ab
constraint (10*c + d) == 3 * (10*a + b);

% da is 2 times bc
constraint (10*d + a) == 2 * (10*b + c);

solve satisfy;

output [
    "{",
    join(",", [
        "\"" ++ "a" ++ "\": " ++ show(a),
        "\"" ++ "b" ++ "\": " ++ show(b),
        "\"" ++ "c" ++ "\": " ++ show(c),
        "\"" ++ "d" ++ "\": " ++ show(d)
    ]),
    "}"
];
