% Input data
int: n = 20; % total steps
set of int: MOVES = {3, 4, 5}; % allowed step sizes
int: max_moves = n div min(MOVES) + 1; % maximum possible moves needed

% Decision Variables
array[1..max_moves] of var 0..5: steps; % steps taken at each move (0 means no move)
var int: total_moves; % number of moves actually used

% Constraints
constraint sum(steps) == n; % total steps must sum to n
constraint forall(i in 1..max_moves) (
    steps[i] in {0} union MOVES
);
constraint forall(i in 1..max_moves-1) (
    steps[i] > 0 -> steps[i+1] >= 0
);
constraint steps[total_moves] > 0;
constraint (total_moves < max_moves) -> (steps[total_moves+1] == 0);

% Calculate total_moves
constraint total_moves = max([i | i in 1..max_moves where steps[i] > 0]);

% Solve (find any valid solution)
solve satisfy;

% Output the solution in JSON format
output [
    "{",
    "\"steps\": ", show(steps),
    "}"
];
```

