include "globals.mzn";

% Children: Bernice, Carl, Debby, Sammy, Ted
enum CHILD = {Bernice, Carl, Debby, Sammy, Ted};

% Ages: 3, 5, 7, 8, 10
set of int: AGE = {3, 5, 7, 8, 10};

% Countries: Ethiopia, Kazakhstan, Lithuania, Morocco, Yemen
enum COUNTRY = {Ethiopia, Kazakhstan, Lithuania, Morocco, Yemen};

% Stories: burning_bush, captivity, moses_youth, passover, ten_commandments
enum STORY = {burning_bush, captivity, moses_youth, passover, ten_commandments};

% Decision Variables
array[CHILD] of var AGE: ages;
array[CHILD] of var COUNTRY: countries;
array[CHILD] of var STORY: stories;

% Constraints
constraint all_different(ages);
constraint all_different(countries);
constraint all_different(stories);

% 1. Debby’s family is from Lithuania.
constraint countries[Debby] = Lithuania;

% 2. The child who told the story of the Passover is two years older than Bernice.
constraint exists(c in CHILD) (
    stories[c] = passover /\ ages[c] = ages[Bernice] + 2
);

% 3. The child whose family is from Yemen is younger than the child from the Ethiopian family.
constraint exists(y in CHILD, e in CHILD) (
    countries[y] = Yemen /\ countries[e] = Ethiopia /\ ages[y] < ages[e]
);

% 4. The child from the Moroccan family is three years older than Ted.
constraint exists(m in CHILD) (
    countries[m] = Morocco /\ ages[m] = ages[Ted] + 3
);

% 5. Sammy is three years older than the child who told the story of Moses’s youth in the house of the Pharaoh.
constraint exists(m in CHILD) (
    stories[m] = moses_youth /\ ages[Sammy] = ages[m] + 3
);

solve satisfy;

% Output the solution in JSON format
output [
    "{",
    join(",", [
        "\"" ++ "ages" ++ "\": " ++ show([fix(ages[c]) | c in CHILD]),
        "\"" ++ "children" ++ "\": " ++ show([show(c) | c in CHILD]),
        "\"" ++ "countries" ++ "\": " ++ show([show(countries[c]) | c in CHILD]),
        "\"" ++ "stories" ++ "\": " ++ show([show(stories[c]) | c in CHILD])
    ]),
    "}"
];
```

