include "globals.mzn";

% Number of cows and sons
int: num_cows = 25;
int: num_sons = 5;

% Milk production for each cow
array[1..num_cows] of int: milk = [i | i in 1..num_cows];

% Number of cows each son should get
array[0..num_sons-1] of int: cows_per_son = [7, 6, 5, 4, 3];

% Decision variable: assignment of cows to sons (0 to 4)
array[1..num_cows] of var 0..num_sons-1: cow_assignments;

% Total milk per son should be equal
var int: total_milk;
constraint total_milk = sum([milk[i] | i in 1..num_cows]) div num_sons;

% Each son gets the correct number of cows
constraint global_cardinality(cow_assignments, [s | s in 0..num_sons-1], cows_per_son);

% All sons have equal total milk
constraint forall(s in 0..num_sons-1) (
    sum([milk[i] * (cow_assignments[i] == s) | i in 1..num_cows]) == total_milk
);

solve satisfy;

output [
    "{\n",
    "\"cow_assignments\": ", show(cow_assignments), "\n",
    "}"
];
```

