include "globals.mzn";

% The prices of the four items in cents (to avoid floating point issues)
array[1..4] of var 1..711: prices;

% The sum of the prices is 711 cents ($7.11)
constraint sum(prices) = 711;

% The product of the prices is 711 * 100^3 cents (since $7.11^4 would be in dollars, but we need to adjust for cents)
% To avoid very large numbers, we can work in cents and adjust the product constraint:
% The product in cents would be (p1 * p2 * p3 * p4) = 711 * 100^3
constraint product(prices) = 711 * 100 * 100 * 100;

% Break symmetry by enforcing non-decreasing order
constraint increasing(prices);

solve satisfy;

output [
    "{",
    "\"prices\": ", show(prices),
    "}"
];
```

