% Decision Variables: apples[i] represents the number of apples before gate i (1..5) and after the last gate (6)
array[1..6] of var int: apples;

% Constraints
constraint apples[6] = 0; % After giving to the girl, no apples left

% For each gate, the number of apples after bribing is current_apples - (floor(current_apples/2) + 1)
constraint forall(g in 1..5) (
    apples[g+1] = apples[g] - (apples[g] div 2 + 1)
);

% All apples counts must be positive integers before the last gate
constraint forall(g in 1..5) (apples[g] > 0);

% Ensure the bribes result in integer apples given (implicit from integer division)

solve satisfy;

output [
    "{\n",
    "    \"apples\": ", show(apples), "\n",
    "}"
];
```

