```minizinc
include "globals.mzn";

% Input data
int: num_people = 8;
array[1..num_people] of set of int: compatible = [
    {2, 3},
    {1, 6},
    {1, 4, 7},
    {2},
    {2},
    {5},
    {8},
    {3}
];

% Decision Variables
array[1..num_people, 1..num_people] of var 0..1: transplants;

% Constraints
% 1. No self-donation
constraint forall(i in 1..num_people)(transplants[i,i] == 0);

% 2. Only donate to compatible people
constraint forall(i in 1..num_people)(
    forall(j in 1..num_people where j != i)(
        transplants[i,j] == 1 -> j in compatible[i]
    )
);

% 3. Each person can donate to at most one person
constraint forall(i in 1..num_people)(
    sum([transplants[i,j] | j in 1..num_people]) <= 1
);

% 4. Each person can receive at most one kidney
constraint forall(j in 1..num_people)(
    sum([transplants[i,j] | i in 1..num_people]) <= 1
);

% 5. If a person donates, they must receive a kidney
constraint forall(i in 1..num_people)(
    (sum([transplants[i,j] | j in 1..num_people]) == 1) -> 
    (sum([transplants[k,i] | k in 1..num_people]) == 1)
);

% Objective: Maximize the number of people receiving a kidney
var int: num_transplants = sum([transplants[i,j] | i,j in 1..num_people]);
solve maximize num_transplants;

% Output the solution in JSON format
output [
    "{",
    "\"" ++ "transplants" ++ "\": [",
    join(",\n", [
        "[" ++ join(",", [show(transplants[i,j]) | j in 1..num_people]) ++ "]" 
        | i in 1..num_people
    ]),
    "]",
    "}"
];
```

