int: n = 4;
int: magic_sum = n * (n*n + 1) div 2;

array[1..n, 1..n] of var 1..n*n: square;

constraint all_different([square[i, j] | i in 1..n, j in 1..n]);

% Row sums
constraint forall(i in 1..n) (
    sum([square[i, j] | j in 1..n]) = magic_sum
);

% Column sums
constraint forall(j in 1..n) (
    sum([square[i, j] | i in 1..n]) = magic_sum
);

% Diagonal sums
constraint sum([square[i, i] | i in 1..n]) = magic_sum;
constraint sum([square[i, n - i + 1] | i in 1..n]) = magic_sum;

solve satisfy;

output [
    "{\n",
    "    \"square\": ", show([ [fix(square[i, j]) | j in 1..n] | i in 1..n ]), "\n",
    "}"
];
```

