```minizinc
include "globals.mzn";

% Input data
int: n = 8;
array[1..n] of set of int: adjacency_list = [
    {2, 3, 7},
    {1, 4, 8},
    {1, 4, 5},
    {2, 3, 6},
    {3, 6, 7},
    {4, 5, 8},
    {1, 5, 8},
    {2, 6, 7}
];

% Decision Variables: nodes[i] = true if node i is in the independent set
array[1..n] of var bool: nodes;

% Constraints
% 1. No two adjacent nodes can both be in the independent set
constraint forall(i in 1..n, j in adjacency_list[i]) (
    not (nodes[i] /\ nodes[j])
);

% 2. The set must be maximal (cannot add any more nodes without violating independence)
constraint forall(i in 1..n where not nodes[i]) (
    exists(j in adjacency_list[i]) (nodes[j])
);

solve satisfy;

% Output the solution in JSON format
output [
    "{",
    "\"nodes\": ", show(nodes),
    "}"
];
```

