constraint artie + bill + crackitt + dodgy + edgy + fingers <= 2;

% Artie's statement: "It wasn't me." 
% If innocent (artie=0), then statement is true (artie=0)
% If guilty (artie=1), then statement is false (artie=1)
constraint (artie == 0) <-> (artie == 0);

% Bill's statement: "Crackitt was in it up to his neck."
% If innocent (bill=0), then crackitt=1
% If guilty (bill=1), then crackitt=0
constraint (bill == 0) <-> (crackitt == 1);

% Crackitt's statement: "No I wasn't."
% If innocent (crackitt=0), then crackitt=0
% If guilty (crackitt=1), then crackitt=1
constraint (crackitt == 0) <-> (crackitt == 0);

% Dodgy's statement: "If Crackitt did it, Bill did it with him."
% If innocent (dodgy=0), then (crackitt -> bill)
% If guilty (dodgy=1), then not (crackitt -> bill)
constraint (dodgy == 0) <-> ((crackitt == 1) -> (bill == 1));

% Edgy's statement: "Nobody did it alone."
% If innocent (edgy=0), then sum of guilty != 1
% If guilty (edgy=1), then sum of guilty == 1
constraint (edgy == 0) <-> (artie + bill + crackitt + dodgy + edgy + fingers != 1);

% Fingers' statement: "That’s right: it was Artie and Dodgy together."
% If innocent (fingers=0), then artie=1 and dodgy=1
% If guilty (fingers=1), then not (artie=1 and dodgy=1)
constraint (fingers == 0) <-> ((artie == 1) /\ (dodgy == 1));

solve satisfy;

output [
    "{",
    join(",", [
        "\"" ++ "artie" ++ "\": " ++ show(artie),
        "\"" ++ "bill" ++ "\": " ++ show(bill),
        "\"" ++ "crackitt" ++ "\": " ++ show(crackitt),
        "\"" ++ "dodgy" ++ "\": " ++ show(dodgy),
        "\"" ++ "edgy" ++ "\": " ++ show(edgy),
        "\"" ++ "fingers" ++ "\": " ++ show(fingers)
    ]),
    "}"
];
