constraint forall(i in 1..size, j in 1..size)(
    steps[N, i, j] == puzzle_end[i, j]
);

% Transition constraints between steps
constraint forall(t in 0..N-1)(
    % Find the position of the empty tile (0) in step t
    exists(empty_i in 1..size, empty_j in 1..size)(
        steps[t, empty_i, empty_j] == 0 /\
        % The empty tile can move to adjacent positions
        (exists(di in -1..1, dj in -1..1 where abs(di) + abs(dj) == 1 /\ 
            empty_i + di >= 1 /\ empty_i + di <= size /\
            empty_j + dj >= 1 /\ empty_j + dj <= size)(
            % Swap the empty tile with an adjacent tile
            steps[t+1, empty_i, empty_j] == steps[t, empty_i + di, empty_j + dj] /\
            steps[t+1, empty_i + di, empty_j + dj] == 0 /\
            % All other tiles remain the same
            forall(i in 1..size, j in 1..size where 
                not (i == empty_i /\ j == empty_j) /\
                not (i == empty_i + di /\ j == empty_j + dj))(
                steps[t+1, i, j] == steps[t, i, j]
            )
        )
    )
);

solve satisfy;

% Output the solution in JSON format
output [
    "{\n",
    "\"steps\": [\n",
    join(",\n", [
        "[" ++ join(",\n", [
            "[" ++ join(",", [show(steps[t, i, j]) | j in 1..size]) ++ "]" 
            | i in 1..size
        ]) ++ "]"
        | t in 0..N
    ]),
    "\n]\n}"
];
