include "globals.mzn";

% Input data
array[1..3] of string: names = ["Agatha herself", "the butler", "Charles"];

% Decision Variables
array[1..3, 1..3] of var bool: hates; % hates[i,j] = true if person i hates person j
array[1..3] of var bool: richer; % richer[i] = true if person i is richer than Agatha
var 1..3: killer; % index of the killer (1: Agatha, 2: butler, 3: Charles)

% Constraints

% A killer always hates, and is no richer than his victim (Agatha)
constraint hates[killer, 1] == true; % killer hates Agatha
constraint richer[killer] == false; % killer is no richer than Agatha

% Charles hates noone that Agatha hates
constraint forall(j in 1..3)(hates[1,j] -> not hates[3,j]);

% Agatha hates everybody except the butler
constraint hates[1,1] == false; % Agatha doesn't hate herself
constraint hates[1,2] == false; % Agatha doesn't hate the butler
constraint hates[1,3] == true; % Agatha hates Charles

% The butler hates everyone not richer than Aunt Agatha
constraint forall(i in 1..3)((not richer[i]) -> hates[2,i]);

% The butler hates everyone whom Agatha hates
constraint forall(i in 1..3)(hates[1,i] -> hates[2,i]);

% Noone hates everyone
constraint forall(i in 1..3)(not forall(j in 1..3)(hates[i,j]));

% Solve
solve satisfy;

% Output
output [
    "{\n",
    "\"killer\": ", show(killer), "\n",
    "}"
];
