include "globals.mzn";

% Input data
int: n_slots = 9;
int: n_templates = 2;
int: n_var = 7;
array[1..n_var] of int: demand = [250, 255, 260, 500, 500, 800, 1100];

% Decision Variables
array[1..n_templates, 1..n_slots] of var 0..n_var: layout;
% layout[t, s] = v means template t has variation v in slot s (0 means empty)
array[1..n_templates] of var int: production;
% production[t] is the number of sheets printed from template t

% Constraints
constraint forall(t in 1..n_templates) (
    production[t] >= 0
);

% Each variation's demand must be met by the sum over all templates and slots
constraint forall(v in 1..n_var) (
    sum([production[t] * bool2int(layout[t, s] == v) | t in 1..n_templates, s in 1..n_slots]) >= demand[v]
);

% Each slot in a template must be either empty (0) or contain a valid variation (1..n_var)
constraint forall(t in 1..n_templates, s in 1..n_slots) (
    layout[t, s] >= 0 /\ layout[t, s] <= n_var
);

% Objective: Minimize the total production (printed sheets)
solve minimize sum(production);

% Output the solution in JSON format
output [
    "{",
    join(",", [
        "\"" ++ "production" ++ "\": " ++ show(production),
        "\"" ++ "layout" ++ "\": " ++ show2d(layout)
    ]),
    "}"
];

