            (assign[w, g, p1] == g1 /\ assign[w, g, p2] == g2) \/
            (assign[w, g, p1] == g2 /\ assign[w, g, p2] == g1)
        )
    ) | w in 1..n_weeks]) <= 1
);

% Break symmetry: first week is fixed
constraint forall(g in 1..n_groups, p in 1..group_size) (
    assign[1, g, p] = (g-1)*group_size + p
);

% Break symmetry: order within groups is irrelevant
constraint forall(w in 1..n_weeks, g in 1..n_groups) (
    increasing([assign[w, g, p] | p in 1..group_size])
);

solve satisfy;

