int: n_days = 18;

enum TEAMS = {Clem, Duke, FSU, GT, UMD, UNC, NCSt, UVA, Wake};
enum STATUS = {Home, Away, Bye};

array[TEAMS, 1..n_days] of var STATUS: where;
array[TEAMS, 1..n_days] of var TEAMS: config;

% Mirroring scheme
set of int: mirror_pairs = {1, 2, 3, 4, 5, 6, 7, 10, 11};
array[mirror_pairs] of int: mirror_dates = [8, 9, 12, 13, 14, 15, 16, 17, 18];

