set of TEAMS: rivals = {Duke, UNC, Clem, GT, NCSt, Wake, UMD, UVA};
array[rivals] of TEAMS: rival_of = [UNC, Duke, GT, Clem, Wake, NCSt, UVA, UMD];

% Constraint 1: Mirroring
constraint forall(t in TEAMS, r in mirror_pairs) (
    config[t, r] = config[t, mirror_dates[r]] /\
    where[t, r] = where[t, mirror_dates[r]]
);

% Constraint 2: No Two Final Aways
constraint forall(t in TEAMS) (
    not (where[t, n_days-1] = Away /\ where[t, n_days] = Away)
);

% Constraint 3: Home/Away/Bye Pattern Constraints
constraint forall(t in TEAMS) (
    % No more than two away in a row
    forall(d in 1..n_days-2) (
        not (where[t, d] = Away /\ where[t, d+1] = Away /\ where[t, d+2] = Away)
    ) /\
    % No more than two home in a row
    forall(d in 1..n_days-2) (
        not (where[t, d] = Home /\ where[t, d+1] = Home /\ where[t, d+2] = Home)
    ) /\
    % No more than three away or byes in a row
    forall(d in 1..n_days-3) (
        not ((where[t, d] = Away \/ where[t, d] = Bye) /\
             (where[t, d+1] = Away \/ where[t, d+1] = Bye) /\
             (where[t, d+2] = Away \/ where[t, d+2] = Bye) /\
             (where[t, d+3] = Away \/ where[t, d+3] = Bye))
    ) /\
    % No more than four home or byes in a row
    forall(d in 1..n_days-4) (
        not ((where[t, d] = Home \/ where[t, d] = Bye) /\
             (where[t, d+1] = Home \/ where[t, d+1] = Bye) /\
             (where[t, d+2] = Home \/ where[t, d+2] = Bye) /\
             (where[t, d+3] = Home \/ where[t, d+3] = Bye) /\
             (where[t, d+4] = Home \/ where[t, d+4] = Bye))
    )
);

% Constraint 4: Weekend Pattern (even dates are weekends)
constraint forall(t in TEAMS) (
    let {
        array[2..n_days step 2] of var STATUS: weekends = [where[t, d] | d in 2..n_days step 2],
        var int: home_weekends = sum([weekends[d] = Home | d in 1..9]),
        var int: away_weekends = sum([weekends[d] = Away | d in 1..9]),
        var int: bye_weekends = sum([weekends[d] = Bye | d in 1..9])
    } in
    home_weekends = 4 /\ away_weekends = 4 /\ bye_weekends = 1
);

% Constraint 5: First Weekends (first five weekends are dates 2,4,6,8,10)
constraint forall(t in TEAMS) (
    sum([where[t, d] != Away | d in {2,4,6,8,10}]) >= 2
);

% Constraint 6: Rival Matches
constraint forall(t in rivals) (
    (where[t, n_days] = Bye \/ config[t, n_days] = FSU) \/
    (config[t, n_days] = rival_of[t] /\ where[t, n_days] != where[rival_of[t], n_days])
);

