    (exists(d in 11..18) (config[GT, d] = Duke \/ config[Duke, d] = GT));

% Constraint 8: Opponent Sequence Constraints
constraint forall(t in TEAMS) (
    forall(d in 1..n_days-1) (
        not (where[t, d] = Away /\ where[t, d+1] = Away /\
             config[t, d] = UNC /\ config[t, d+1] = Duke)
    ) /\
    forall(d in 1..n_days-2) (
        not (config[t, d] = UNC /\ config[t, d+1] = Duke /\ config[t, d+2] = Wake)
    )
);

% Constraint 9: Other Constraints
constraint 
    config[UNC, n_days] = Duke /\
    config[UNC, 11] = Duke /\
    config[UNC, 2] = Clem /\
    where[Duke, 16] = Bye /\
    where[Wake, 17] != Home /\
    where[Wake, 1] = Bye /\
    forall(t in {Clem, Duke, UMD, Wake}) (where[t, n_days] != Away) /\
    forall(t in {Clem, FSU, GT, Wake}) (where[t, 1] != Away) /\
    where[FSU, n_days] != Bye /\
    where[NCSt, n_days] != Bye /\
    where[UNC, 1] != Bye;

% Double round robin constraints
constraint forall(t1, t2 in TEAMS where t1 != t2) (
    sum([config[t1, d] = t2 /\ where[t1, d] = Home | d in 1..n_days]) = 1 /\
    sum([config[t1, d] = t2 /\ where[t1, d] = Away | d in 1..n_days]) = 1
);

% A team cannot play itself
constraint forall(t in TEAMS, d in 1..n_days) (
    config[t, d] != t
);

% If a team is home, the opponent must be away and vice versa
constraint forall(t1 in TEAMS, d in 1..n_days) (
    (where[t1, d] = Home) -> (where[config[t1, d], d] = Away) /\
    (where[t1, d] = Away) -> (where[config[t1, d], d] = Home) /\
    (where[t1, d] = Bye) -> (config[t1, d] = t1)
);

solve satisfy;

output [
    "{\n",
    "\"config\": [\n",
    join(",\n", [
        "[" ++ join(", ", [show(config[t, d]) | d in 1..n_days]) ++ "]" | t in TEAMS
    ]),
    "\n],\n",
    "\"where\": [\n",
    join(",\n", [
        "[" ++ join(", ", [show(where[t, d]) | d in 1..n_days]) ++ "]" | t in TEAMS
    ]),
    "\n]\n}"
];
