```minizinc
include "globals.mzn";

% Input data
int: n_boats = 5;
int: n_periods = 4;
array[1..n_boats] of int: capacity = [6, 8, 12, 12, 12];
array[1..n_boats] of int: crew_size = [2, 2, 2, 2, 4];

% Decision Variables
array[1..n_boats] of var bool: is_host;
array[1..n_boats, 1..n_periods] of var 0..n_boats: visits;

% Constraints
% A boat is either a host or a guest (but not both)
constraint forall(b in 1..n_boats) (
    if is_host[b] then
        forall(p in 1..n_periods) (visits[b, p] = 0)
    else
        exists(p in 1..n_periods) (visits[b, p] != 0)
    endif
);

% Guest boats cannot revisit a host
constraint forall(b in 1..n_boats where not is_host[b]) (
    alldifferent([visits[b, p] | p in 1..n_periods where visits[b, p] != 0])
);

% Guest crews cannot meet more than once
constraint forall(b1, b2 in 1..n_boats where b1 < b2) (
    sum(p in 1..n_periods) (visits[b1, p] != 0 /\ visits[b2, p] != 0 /\ visits[b1, p] == visits[b2, p]) <= 1
);

% Capacity constraints
constraint forall(h in 1..n_boats where is_host[h]) (
    forall(p in 1..n_periods) (
        crew_size[h] + sum(b in 1..n_boats where not is_host[b] /\ visits[b, p] == h) (crew_size[b]) <= capacity[h]
    )
);

% Objective: minimize the number of host boats
solve minimize sum(is_host);

% Output the solution in JSON format
output [
    "{",
    join(",", [
        "\"" ++ "visits" ++ "\": " ++ show2d(visits),
        "\"" ++ "is_host" ++ "\": " ++ show(is_host)
    ]),
    "}"
];

% Helper function to show 2D arrays
function string: show2d(array[int, int] of var int: x) =
    "[" ++ join(",\n", [
        "[" ++ join(",", [show(x[i, j]) | j in 1..n_periods]) ++ "]" | i in 1..n_boats
    ]) ++ "]";
