% Input data
int: n = 13;  % Number of balls
int: c = 3;   % Number of boxes

% Decision Variables
array[1..n, 1..c] of var bool: M;  % M[i,j] is true if ball i is in box j
array[1..n] of var 1..c: balls;     % Assignment of balls to boxes (1..3)

% Constraints
% Each ball must be in exactly one box
constraint forall(i in 1..n) (
    sum([M[i,j] | j in 1..c]) = 1
);

% Link M and balls variables
constraint forall(i in 1..n) (
    sum([j * M[i,j] | j in 1..c]) = balls[i]
);

% For each x + y = z, not all three in the same box
constraint forall(x in 1..n, y in 1..n, z in 1..n where x + y = z) (
    forall(j in 1..c) (
        M[x,j] + M[y,j] + M[z,j] <= 2
    )
);

solve satisfy;

% Output the assignment of balls to boxes
output [
    "{\n",
    "    \"balls\": ", show(balls), "\n",
    "}"
];
