include "globals.mzn";

% Input data
int: k = 4; % Number of sets
int: n = 9; % Numbers from 1 to n (since L(3,9) is mentioned as example)
int: total_numbers = k * n;

% Decision Variables
array[1..total_numbers] of var 1..n: solution;
array[1..n, 1..k] of var 1..total_numbers: position; % position[m, s] is the index of the s-th occurrence of m in the sequence

% Constraints
constraint forall(m in 1..n, s in 1..k-1) (
    position[m, s+1] = position[m, s] + m + 1
);

% All positions must be within the sequence length
constraint forall(m in 1..n, s in 1..k) (
    position[m, s] >= 1 /\ position[m, s] <= total_numbers
);

% All positions must be distinct
constraint alldifferent([position[m, s] | m in 1..n, s in 1..k]);

% Fill the solution array based on positions
constraint forall(m in 1..n, s in 1..k) (
    solution[position[m, s]] = m
);

% Ensure that all numbers are used exactly k times
constraint global_cardinality(solution, [m | m in 1..n], [k | m in 1..n]);

solve satisfy;

output [
    "{",
    join(",", [
        "\"" ++ "position" ++ "\": " ++ show2d(position),
        "\"" ++ "solution" ++ "\": " ++ show(solution)
    ]),
