include "globals.mzn";

int: n_teams = 8;
int: n_weeks = n_teams - 1;
int: n_periods = n_teams div 2;

% Decision variables: home and away teams for each week and period
array[1..n_weeks, 1..n_periods, 1..2] of var 0..n_teams-1: home;
array[1..n_weeks, 1..n_periods, 1..2] of var 0..n_teams-1: away;

% Constraints

% Every team plays once a week
constraint forall(w in 1..n_weeks) (
    alldifferent([home[w, p, s] | p in 1..n_periods, s in 1..2] ++ 
                 [away[w, p, s] | p in 1..n_periods, s in 1..2])
);

% Every team plays at most twice in the same period over the tournament
constraint forall(t in 0..n_teams-1, p in 1..n_periods) (
    count([home[w, p, s] = t \/ away[w, p, s] = t | w in 1..n_weeks, s in 1..2], true) <= 2
);

% Every team plays every other team (single round robin)
constraint forall(t1 in 0..n_teams-1, t2 in 0..n_teams-1 where t1 != t2) (
    exists(w in 1..n_weeks, p in 1..n_periods, s in 1..2) (
        (home[w, p, s] = t1 /\ away[w, p, s] = t2) \/
        (home[w, p, s] = t2 /\ away[w, p, s] = t1)
    )
);

% Additional constraints to ensure valid pairings
constraint forall(w in 1..n_weeks, p in 1..n_periods) (
    home[w, p, 1] != away[w, p, 1] /\
    home[w, p, 2] != away[w, p, 2]
);

% Symmetry breaking: fix first week's matches
constraint 
    home[1, 1, 1] = 0 /\ away[1, 1, 1] = 1 /\
    home[1, 1, 2] = 2 /\ away[1, 1, 2] = 3 /\
    home[1, 2, 1] = 4 /\ away[1, 2, 1] = 5 /\
    home[1, 2, 2] = 6 /\ away[1, 2, 2] = 7;

solve satisfy;

output [
    "{",
    "\"home\": " ++ show3d(home) ++ ", ",
    "\"away\": " ++ show3d(away),
    "}"
];

% Helper function to show 3D arrays
function string: show3d(array[int, int, int] of var int: x) =
    "[" ++ join(", ", 
        [ "[" ++ join(", ", 
            [ "[" ++ join(", ", [show(x[w, p, s]) | s in 1..2]) ++ "]" 
            | p in 1..n_periods ]) ++ "]" 
        | w in 1..n_weeks ]) ++ "]";
```

