    sum([bool2int(words[w, p] == C \/ words[w, p] == G) | p in POS]) == 4
);

% Each pair of distinct words differs in at least 4 positions
constraint forall (w1, w2 in WORDS where w1 < w2) (
    sum([bool2int(words[w1, p] != words[w2, p]) | p in POS]) >= 4
);

% Function to compute reverse of a word
function array[POS] of var NUCLEOTIDE: reverse_word(array[POS] of var NUCLEOTIDE: x) =
    [x[word_length - p + 1] | p in POS];

% Function to compute Watson-Crick complement of a word
function array[POS] of var NUCLEOTIDE: complement_word(array[POS] of var NUCLEOTIDE: y) =
    [if y[p] == A then T 
     elseif y[p] == T then A 
     elseif y[p] == C then G 
     else A endif | p in POS]; % Note: The else case is a fallback, but should not occur

% Each pair of words x and y (may be identical) must satisfy that x^R and y^C differ in at least 4 positions
constraint forall (x, y in WORDS) (
    sum([bool2int(reverse_word(words[x])[p] != complement_word(words[y])[p]) | p in POS]) >= 4
);

% Solve statement - we want to find any valid set of words
solve satisfy;

% Output the solution in JSON format
output [
    "{",
    "\"words\": [",
    join(",\n    ", [
        "[" ++ join(", ", [show(words[w, p]) | p in POS]) ++ "]" 
        | w in WORDS
    ]),
    "]",
    "}"
];
