include "globals.mzn";

% Friends: Debra=0, Janet=1, Hugh=2, Rick=3
enum FRIENDS = {Debra, Janet, Hugh, Rick};

% Allergies: eggs, mold, nuts, ragweed
enum ALLERGIES = {eggs, mold, nuts, ragweed};

% Surnames: Baxter, Lemon, Malone, Fleet
enum SURNAMES = {Baxter, Lemon, Malone, Fleet};

% Decision Variables
array[FRIENDS] of var ALLERGIES: allergy;
array[FRIENDS] of var SURNAMES: surname;

% Constraints
constraint allergy[Rick] != mold; % Rick is not allergic to mold
constraint surname[Debra] != Lemon; % Janet isn't Lemon (and Debra is not Janet)
constraint surname[Janet] != Lemon; % Janet isn't Lemon
constraint surname[Hugh] != Lemon /\ surname[Hugh] != Fleet; % Hugh is neither Lemon nor Fleet
constraint allergy[Debra] == ragweed; % Debra is allergic to ragweed
constraint allergy[Janet] != eggs /\ allergy[Janet] != mold; % Janet is neither allergic to eggs nor to mold

% Baxter is allergic to eggs
constraint exists(f in FRIENDS)(
    surname[f] == Baxter /\ allergy[f] == eggs
);

% All allergies and surnames must be assigned uniquely
constraint all_different(allergy);
constraint all_different(surname);

solve satisfy;

output [
    "{",
