% Guests are represented as integers:
% 0: Andrew, 1: Betty, 2: Cara, 3: Dave, 4: Erica, 5: Frank
int: num_guests = 6;
set of int: GUESTS = 0..num_guests-1;

% Define who can sit next to whom (1 if allowed, 0 otherwise)
array[GUESTS, GUESTS] of int: allowed = array2d(GUESTS, GUESTS, [
    % A  B  C  D  E  F
    [0, 0, 0, 1, 0, 1], % Andrew (0)
    [0, 0, 1, 0, 1, 0], % Betty (1)
    [0, 1, 0, 0, 0, 1], % Cara (2)
    [1, 0, 0, 0, 1, 0], % Dave (3)
    [0, 1, 0, 1, 0, 0], % Erica (4)
    [1, 0, 1, 0, 0, 0]  % Frank (5)
]);

% Decision variable: seating arrangement (circular)
array[1..num_guests] of var GUESTS: x;

% Constraints
constraint alldifferent(x);

% Count conflicts (when allowed[i,j] = 0 but they are neighbors)
var int: conflicts = 
    sum(i in 1..num_guests) (
        allowed[x[i], x[(i mod num_guests) + 1]] == 0
    );

% Minimize conflicts
solve minimize conflicts;

output [
    "{\n",
    "\"x\": ", show(x), "\n",
    "}"
];
```

