int: n = 5;
set of int: Rows = 1..n;
set of int: Cols = 1..n;
set of int: Positions = 1..n*n;

array[Rows, Cols] of var Positions: x;

% Ensure all numbers from 1 to n^2 are present exactly once
constraint alldifferent([x[i,j] | i in Rows, j in Cols]);

% Movement constraints
constraint forall(i in Rows, j in Cols where x[i,j] < n*n) (
    exists(
        % Movement Type I: horizontal or vertical, exactly 3 squares away (2 gap)
        [
            (abs(i - k) == 3 /\ j == l /\ x[k,l] == x[i,j] + 1) \/
            (abs(j - l) == 3 /\ i == k /\ x[k,l] == x[i,j] + 1)
        | k in Rows, l in Cols where (abs(i - k) == 3 /\ j == l) \/ (abs(j - l) == 3 /\ i == k)
        ] ++
        % Movement Type II: diagonal, exactly 2 squares away (1 gap)
        [
            (abs(i - k) == 2 /\ abs(j - l) == 2 /\ x[k,l] == x[i,j] + 1)
        | k in Rows, l in Cols where abs(i - k) == 2 /\ abs(j - l) == 2
        ]
    )
);

solve satisfy;

output [
    "{\n",
    "\"x\": ", show2d(x), "\n",
    "}"
];

function string: show2d(array[int,int] of var int: a) =
    let {
        int: rows = card(index_set_1of2(a));
        int: cols = card(index_set_2of2(a));
        array[1..rows] of string: row_str = [
            "[" ++ join(", ", [show(a[i,j]) | j in 1..cols]) ++ "]" | i in 1..rows
        ];
    } in
    "[" ++ join(",\n ", row_str) ++ "]";
