int: min_a = 2012;

% Decision Variables
var int: a;
var int: b;
var int: n;
var int: p;

% Constraints
constraint a >= min_a;
constraint b >= 1;
constraint p >= 2;
constraint a - b == p;
constraint a * b == n * n;

% Primality check for p (using trial division up to sqrt(p))
predicate is_prime(var int: num) =
    num >= 2 /\
    forall(i in 2..floor(sqrt(int2float(num))) + 1) (
        num mod i != 0
    );

constraint is_prime(p);

% Solve to minimize a
solve minimize a;

% Output in JSON format
output [
    "{",
    join(",", [
        "\"" ++ "a" ++ "\": " ++ show(a),
        "\"" ++ "b" ++ "\": " ++ show(b),
        "\"" ++ "n" ++ "\": " ++ show(n),
        "\"" ++ "p" ++ "\": " ++ show(p)
    ]),
    "}"
];
