% Input data
int: num_moves = 3;
array[1..3] of int: init = [1, 0, 1];

% Decision Variables
array[1..num_moves, 1..3] of var 0..1: steps; % Each move can flip any of the 3 coins (0: no flip, 1: flip)

% Constraints
% The final state after all moves should be all heads (0) or all tails (1)
constraint 
    let {
        array[1..3] of var 0..1: final_state = 
            [ (init[i] + sum([steps[m, i] | m in 1..num_moves])) mod 2 | i in 1..3 ]
    } in
    (all_equal(final_state));

% Solve
solve satisfy;

% Output
output [
    "{",
    "\"steps\": ", show(steps),
    "}"
];
```

